import { Component, ChangeDetectionStrategy, inject, signal, computed, output } from '@angular/core';
import { PatientsService } from '../services/patients.service';
import { EpisodeData, SubmissionStatus } from '../models/patient.model';
import { EpisodeListComponent } from './episode-list';

@Component({
  selector: 'app-patient-detail',
  standalone: true,
  imports: [EpisodeListComponent],
  templateUrl: './patient-detail.html',
  styleUrl: './patient-detail.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PatientDetailComponent {
  private patientsService = inject(PatientsService);

  // Signals from service
  readonly patientDetail = this.patientsService.selectedPatient;
  readonly loading = this.patientsService.loadingDetail;

  // Computed values
  readonly client = computed(() => this.patientDetail()?.client);
  readonly episodes = computed(() => this.patientDetail()?.episodes ?? []);
  readonly episodeCount = computed(() => this.episodes().length);

  // SDOH completeness
  readonly sdohComplete = computed(() => this.client()?.sdoh_complete_ind === 1);
  readonly sdohMissingFields = computed(() => {
    const missing = this.client()?.sdoh_missing_fields ?? '';
    return missing ? missing.split(',').map(f => f.trim()) : [];
  });

  // Outputs
  viewEpisode = output<EpisodeData>();
  viewLogs = output<number>(); // Emit person_id

  // Section collapse state
  readonly expandedSections = signal<Set<string>>(new Set(['demographics', 'identifiers', 'address', 'sdoh']));

  toggleSection(section: string): void {
    this.expandedSections.update(set => {
      const newSet = new Set(set);
      if (newSet.has(section)) {
        newSet.delete(section);
      } else {
        newSet.add(section);
      }
      return newSet;
    });
  }

  isSectionExpanded(section: string): boolean {
    return this.expandedSections().has(section);
  }

  getStatusClass(status: SubmissionStatus | undefined): string {
    switch (status) {
      case 'SUBMITTED': return 'status-success';
      case 'ERROR': return 'status-error';
      case 'PENDING': return 'status-pending';
      case 'PARTIAL': return 'status-partial';
      default: return '';
    }
  }

  onViewRelatedLogs(): void {
    const personId = this.client()?.person_id;
    if (personId) {
      this.viewLogs.emit(personId);
    }
  }

  formatDate(date: string | undefined): string {
    if (!date) return '-';
    try {
      return new Date(date).toLocaleDateString('en-CA');
    } catch {
      return date;
    }
  }
}
