/**
 * TypeScript interfaces for MHA PDS patient data structures
 * Follows MHA PDS 1.2 Logical Data Dictionary specifications
 */

// Submission status types
export type SubmissionStatus = 'PENDING' | 'SUBMITTED' | 'ERROR' | 'PARTIAL' | '';

/**
 * Patient list item (summary for table display)
 */
export interface PatientListItem {
  client_id: number;
  person_id: number;
  episode_id: number;
  first_name: string;
  last_name: string;
  date_of_birth: string;
  date_of_birth_formatted: string;
  mrn: string;
  hcn: string;
  submission_status: SubmissionStatus;
  functional_centre: string;
  functional_centre_mapped: string;
  program_name: string;
  episode_count: number;
  latest_episode_date: string;
  latest_episode_date_formatted: string;
  sdoh_complete_ind: number;
}

/**
 * Full patient detail with nested data
 */
export interface PatientDetail {
  found_ind: number;
  client: ClientData;
  episodes: EpisodeData[];
}

/**
 * DE01-DE04 Client data (point-in-time snapshot)
 */
export interface ClientData {
  client_id: number;
  person_id: number;
  episode_id: number;
  extracted_dt_tm: string;
  extracted_dt_tm_formatted: string;

  // DE01 - Client Information
  de01_001_first_name: string;
  de01_002_middle_name: string;
  de01_003_last_name: string;
  de01_004_date_of_birth: string;
  de01_004_date_of_birth_formatted: string;
  de01_005_estimated_dob_flag: number;

  // DE02 - Client Identifiers
  de02_001_mrn: string;
  de02_002_vendor_id: string;
  de02_003_hcn: string;
  de02_004_hcn_type: string;
  de02_005_issuing_authority: string;

  // DE03 - Client Address
  de03_001_address_use: string;
  de03_002_city: string;
  de03_003_province: string;
  de03_004_postal_code: string;

  // DE04 - Socio-Demographic Data (SDOH) - 21 fields
  de04_001_preferred_language: string;
  de04_002_interpreter_needed: string;
  de04_003_birth_country: string;
  de04_004_arrival_date_canada: string;
  de04_005_immigration_status: string;
  de04_006_indigenous_identity: string;
  de04_007_gender_identity: string;
  de04_008_sexual_orientation: string;
  de04_009_veteran_status: string;
  de04_010_disability_status: string;
  de04_011_racial_identity: string;
  de04_012_citizenship_status: string;
  de04_013_education: string;
  de04_014_employment: string;
  de04_015_income_source: string;
  de04_016_income_amount: string;
  de04_017_housing: string;
  de04_018_household_income: string;
  de04_019_household_size: string;
  de04_020_legal_status: string;
  de04_021_french_language_services: string;

  // Metadata
  sdoh_complete_ind: number;
  sdoh_missing_fields: string;
  data_modified_ind: number;
  submission_status: SubmissionStatus;
  submission_dt_tm: string;
  submission_dt_tm_formatted: string;
}

/**
 * DE05, DE06, DE09 Episode data
 */
export interface EpisodeData {
  episode_id: number;
  person_id: number;
  encntr_id: number;
  episode_identifier: string;

  // DE05 - Referral
  referral_id: string;
  referral_received_date: string;
  referral_received_date_formatted: string;
  referral_source: string;
  referral_source_type: string;
  referral_type: string;

  // DE06 - Episode of Care
  episode_of_care_id: string;
  episode_of_care_status: string;
  first_contact_date: string;
  first_contact_date_formatted: string;
  eligibility_screening_date: string;
  eligibility_screening_date_formatted: string;
  initial_assessment_date: string;
  initial_assessment_date_formatted: string;
  scheduled_appointment_date: string;
  scheduled_appointment_date_formatted: string;
  appt_rescheduled_reason: string;
  service_initiation_date: string;
  service_initiation_date_formatted: string;
  service_enrollment_date: string;
  service_enrollment_date_formatted: string;
  service_termination_date: string;
  service_termination_date_formatted: string;
  service_termination_reason: string;

  // DE09 - Health Program
  health_program_number: string;
  health_program_name: string;
  functional_centre: string;
  functional_centre_mapped: string;

  // Submission
  submission_status: SubmissionStatus;
  submission_dt_tm: string;
  submission_dt_tm_formatted: string;
  submission_batch_id: string;
  error_message: string;

  // Nested services for this episode
  service_cnt: number;
  services: ServiceData[];
}

/**
 * DE07, DE08, DE10 Service data
 */
export interface ServiceData {
  service_id: number;
  episode_id: number;
  encntr_id: number;
  person_id: number;

  // DE07 - HSP Organization
  hsp_organization_number: string;
  moh_organization_id: string;
  hsp_organization_name: string;
  hsp_organization_active_flag: number;

  // DE08 - HSP Site
  hsp_site_number: string;
  hsp_site_name: string;

  // DE10 - Health Service Event
  health_service_event_id: string;
  service_modality: string;
  service_modality_type: string;
  encounter_date: string;
  encounter_date_formatted: string;
  health_service_group_id: string;
  direct_service_minutes: number;
  indirect_service_minutes: number;
  encounter_status: string;

  // Additional service info
  service_provider_name: string;
  is_assessment_ind: number;
  no_show_ind: number;
}

/**
 * Filter and pagination types
 */
export interface PatientFilters {
  search_text: string;
  submission_status: SubmissionStatus;
  start_date: string;
  end_date: string;
  functional_centre: string;
  program_name: string;
  page: number;
  page_size: number;
}

/**
 * Response structure for patient list requests
 */
export interface PatientsResponse {
  total_count: number;
  returned_count: number;
  page: number;
  page_size: number;
  patients: PatientListItem[];
}

/**
 * Default filter values
 */
export const DEFAULT_PATIENT_FILTERS: PatientFilters = {
  search_text: '',
  submission_status: '',
  start_date: '',
  end_date: '',
  functional_centre: '',
  program_name: '',
  page: 1,
  page_size: 50
};

