import { ChangeDetectionStrategy, Component, OnInit, inject } from '@angular/core';
import { Router } from '@angular/router';
import { PatientListComponent } from './components/patient-list';
import { PatientDetailComponent } from './components/patient-detail';
import { PatientsService } from './services/patients.service';
import { PatientListItem } from './models/patient.model';

/**
 * Patients component for browsing MHA PDS client data
 * Uses master-detail layout: patient list on left, detail on right
 */
@Component({
  selector: 'app-patients',
  standalone: true,
  imports: [PatientListComponent, PatientDetailComponent],
  templateUrl: './patients.html',
  styleUrl: './patients.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PatientsComponent implements OnInit {
  private patientsService = inject(PatientsService);
  private router = inject(Router);

  // Expose service signals to template
  readonly selectedPatient = this.patientsService.selectedPatient;
  readonly loadingDetail = this.patientsService.loadingDetail;

  ngOnInit(): void {
    // Load initial patient list
    this.patientsService.loadPatients();
  }

  onPatientSelected(patient: PatientListItem): void {
    // Detail loading is handled by the list component
  }

  onViewLogs(personId: number): void {
    // Navigate to logs page
    // Future: Could add person_id filter to logs
    this.router.navigate(['/logs']);
  }
}
