import { Component, ChangeDetectionStrategy, inject, signal, output } from '@angular/core';
import { PatientsService } from '../services/patients.service';
import { PatientListItem, SubmissionStatus } from '../models/patient.model';
import { PatientFiltersComponent } from './patient-filters';

@Component({
  selector: 'app-patient-list',
  standalone: true,
  imports: [PatientFiltersComponent],
  templateUrl: './patient-list.html',
  styleUrl: './patient-list.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PatientListComponent {
  private patientsService = inject(PatientsService);

  // Expose service signals to template
  readonly patients = this.patientsService.patients;
  readonly loading = this.patientsService.loading;
  readonly error = this.patientsService.error;
  readonly totalCount = this.patientsService.totalCount;
  readonly currentPage = this.patientsService.currentPage;
  readonly totalPages = this.patientsService.totalPages;
  readonly hasNextPage = this.patientsService.hasNextPage;
  readonly hasPrevPage = this.patientsService.hasPrevPage;

  // Selection tracking
  readonly selectedClientId = signal<number | null>(null);

  // Output for row selection
  patientSelected = output<PatientListItem>();

  onSelectPatient(patient: PatientListItem): void {
    this.selectedClientId.set(patient.client_id);
    this.patientSelected.emit(patient);
    this.patientsService.loadPatientDetail(patient.client_id);
  }

  onNextPage(): void {
    this.patientsService.nextPage();
  }

  onPrevPage(): void {
    this.patientsService.prevPage();
  }

  isSelected(patient: PatientListItem): boolean {
    return this.selectedClientId() === patient.client_id;
  }

  getStatusClass(status: SubmissionStatus): string {
    switch (status) {
      case 'SUBMITTED': return 'status-success';
      case 'ERROR': return 'status-error';
      case 'PENDING': return 'status-pending';
      case 'PARTIAL': return 'status-partial';
      default: return '';
    }
  }

  getSdohClass(sdohComplete: number): string {
    return sdohComplete === 1 ? 'sdoh-complete' : 'sdoh-incomplete';
  }

  trackByClientId(index: number, patient: PatientListItem): number {
    return patient.client_id;
  }
}
