import { Component, ChangeDetectionStrategy, input, signal } from '@angular/core';
import { EpisodeData, SubmissionStatus } from '../models/patient.model';
import { ServiceListComponent } from './service-list';

@Component({
  selector: 'app-episode-list',
  standalone: true,
  imports: [ServiceListComponent],
  templateUrl: './episode-list.html',
  styleUrl: './episode-list.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class EpisodeListComponent {
  // Input: episodes from parent
  episodes = input.required<EpisodeData[]>();

  // Track expanded episodes
  readonly expandedEpisodes = signal<Set<number>>(new Set());

  toggleEpisode(episodeId: number): void {
    this.expandedEpisodes.update(set => {
      const newSet = new Set(set);
      if (newSet.has(episodeId)) {
        newSet.delete(episodeId);
      } else {
        newSet.add(episodeId);
      }
      return newSet;
    });
  }

  isEpisodeExpanded(episodeId: number): boolean {
    return this.expandedEpisodes().has(episodeId);
  }

  getStatusClass(status: SubmissionStatus | undefined): string {
    switch (status) {
      case 'SUBMITTED': return 'status-success';
      case 'ERROR': return 'status-error';
      case 'PENDING': return 'status-pending';
      case 'PARTIAL': return 'status-partial';
      default: return '';
    }
  }

  trackByEpisodeId(index: number, episode: EpisodeData): number {
    return episode.episode_id;
  }
}
