import { Component, ChangeDetectionStrategy, inject, signal, effect } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { PatientsService } from '../services/patients.service';
import { SubmissionStatus, SUBMISSION_STATUS_OPTIONS } from '../models/patient.model';

@Component({
  selector: 'app-patient-filters',
  standalone: true,
  imports: [FormsModule],
  templateUrl: './patient-filters.html',
  styleUrl: './patient-filters.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PatientFiltersComponent {
  private patientsService = inject(PatientsService);

  // Current filter values from service
  readonly filters = this.patientsService.filters;
  readonly loading = this.patientsService.loading;

  // Filter options
  readonly statusOptions = SUBMISSION_STATUS_OPTIONS;

  // Local form state for immediate binding
  searchText = signal('');
  submissionStatus = signal<SubmissionStatus>('');
  startDate = signal('');
  endDate = signal('');
  functionalCentre = signal('');
  programName = signal('');

  // Debounced search
  private searchDebounce: ReturnType<typeof setTimeout> | null = null;
  private textFilterDebounce: ReturnType<typeof setTimeout> | null = null;

  constructor() {
    // Sync local state with service filters
    effect(() => {
      const f = this.filters();
      this.searchText.set(f.search_text);
      this.submissionStatus.set(f.submission_status);
      this.startDate.set(f.start_date);
      this.endDate.set(f.end_date);
      this.functionalCentre.set(f.functional_centre);
      this.programName.set(f.program_name);
    }, { allowSignalWrites: true });
  }

  onSearchChange(value: string): void {
    this.searchText.set(value);
    // Debounce search to avoid too many requests
    if (this.searchDebounce) {
      clearTimeout(this.searchDebounce);
    }
    this.searchDebounce = setTimeout(() => {
      this.applyFilters();
    }, 300);
  }

  onStatusChange(value: string): void {
    this.submissionStatus.set(value as SubmissionStatus);
    this.applyFilters();
  }

  onDateChange(): void {
    this.applyFilters();
  }

  onFunctionalCentreChange(value: string): void {
    this.functionalCentre.set(value);
    // Debounce text input
    if (this.textFilterDebounce) {
      clearTimeout(this.textFilterDebounce);
    }
    this.textFilterDebounce = setTimeout(() => {
      this.applyFilters();
    }, 300);
  }

  onProgramChange(value: string): void {
    this.programName.set(value);
    // Debounce text input
    if (this.textFilterDebounce) {
      clearTimeout(this.textFilterDebounce);
    }
    this.textFilterDebounce = setTimeout(() => {
      this.applyFilters();
    }, 300);
  }

  applyFilters(): void {
    this.patientsService.loadPatients({
      search_text: this.searchText(),
      submission_status: this.submissionStatus(),
      start_date: this.startDate(),
      end_date: this.endDate(),
      functional_centre: this.functionalCentre(),
      program_name: this.programName()
    });
  }

  resetFilters(): void {
    this.patientsService.resetFilters();
    this.patientsService.loadPatients();
  }

  hasActiveFilters(): boolean {
    const f = this.filters();
    return !!(f.search_text || f.submission_status || f.start_date ||
              f.end_date || f.functional_centre || f.program_name);
  }
}
